UPDATE abschlussnachweis
SET ausstellungsort = 'Nicht erfasst'
WHERE ausstellungsort IS NULL;

ALTER TABLE abschlussnachweis
ALTER COLUMN ausstellungsort SET NOT NULL;

UPDATE lagerplatz
SET pruefstatus = 'ungeprueft'
WHERE pruefstatus IS NULL;

ALTER TABLE lagerplatz
ALTER COLUMN pruefstatus SET NOT NULL;

UPDATE medium
SET lizenzklasse = N'UNGEKLAERT'
WHERE lizenzklasse IS NULL;

ALTER TABLE medium
ALTER COLUMN lizenzklasse NVARCHAR(25) NOT NULL;
